-- Read-only, minimal Admin projections. No fixture writer or dispatch authority.
create index signal_delivery_admin_sequence on private.signal_deliveries(tenant_id,sequence desc);
create index signal_delivery_admin_status on private.signal_deliveries(tenant_id,status,sequence desc);
create function private.signal_admin_code_v1(v text) returns text language sql immutable set search_path=pg_catalog as $$
 select case when v=any(array['QUEUED','SOURCE_RESTRICTED','SOURCE_UNAVAILABLE','PARSE_UNCERTAIN','SOURCE_STALE','POLICY_DISABLED','CONFIG_CHANGED','SOURCE_AGE_REVIEW','LEASE_RECOVERED','UNKNOWN_EFFECT','LEASE_BUDGET','CLAIM_BUDGET','CLAIMED','NO_DESTINATION_MESSAGE','REFERENCE_UNRESOLVED','PAYLOAD_UNSUPPORTED','BEGUN','FAKE_ACK','RECONCILED_FAKE_ACK','KNOWN_FAILURE','RATE_LIMITED','FAILURE_BUDGET']) then v else 'UNRECORDED' end
$$;
create function private.signal_admin_base_v1() returns jsonb language sql immutable set search_path=pg_catalog as $$
 select jsonb_build_object('provider_id',null,'source_id',null,'destination_id',null,'event_id',null,'delivery_id',null,'provider_label',null,'source_label',null,'destination_label',null,
 'revision',null,'observed_at',null,'published_at',null,'recorded_at',null,'acknowledged_at',null,'available_at',null,'code',null,'parse_state',null,'current',null,'paused',null,'authorization',null,'claims',null,'reclaims',null,'failures',null,'signal',null)
$$;
create function private.signal_admin_rows_v1(t uuid,c text,p uuid,s uuid,d uuid,j uuid,st text,ak text,hk text,keys_value text[],lim integer)
returns table(key_value text,row_value jsonb) language plpgsql stable set search_path=pg_catalog as $$
begin
 if c='providers' then return query select x.id::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','PROVIDER','label',x.label,'reference',x.label,'provider_id',x.id,'provider_label',x.label,'state',case when x.paused then 'PAUSED' when x.authorization_status='SYNTHETIC_APPROVED' then 'SIMULATED' else 'CONFIGURED_DISABLED' end,'paused',x.paused,'authorization',x.authorization_status,'revision',x.revision::text) from private.signal_providers x  where x.tenant_id=t and (ak is null or x.id<ak::uuid) and (hk is null or x.id<=hk::uuid) and (keys_value is null or x.id=any(keys_value::uuid[])) and (p is null or x.id=p) order by x.id desc limit least(greatest(lim,1),101);return;end if;
 if c='sources' then return query select x.id::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','SOURCE','label',x.label,'reference',x.label,'provider_id',v.id,'provider_label',v.label,'source_id',x.id,'source_label',x.label,'state',case when x.paused or v.paused then 'PAUSED' when v.authorization_status<>'SYNTHETIC_APPROVED' then 'CONFIGURED_DISABLED' when e.kind='RESTRICTED' then 'SOURCE_RESTRICTED' when e.kind='UNAVAILABLE' then 'SOURCE_UNAVAILABLE' when e.id is null then 'NO_OBSERVATION' else 'SIMULATED' end,'paused',x.paused,'authorization',v.authorization_status,'revision',x.revision::text,'observed_at',e.original->>'observed_at','recorded_at',e.recorded_at,'event_id',e.id,'parse_state',e.parse_state) from private.signal_sources x join private.signal_providers v on v.tenant_id=x.tenant_id and v.id=x.provider_id left join lateral(select q.id,q.kind,q.parse_state,q.recorded_at,q.original from private.signal_events q where q.tenant_id=t and q.source_id=x.id order by q.sequence desc limit 1)e on true where x.tenant_id=t and (ak is null or x.id<ak::uuid) and (hk is null or x.id<=hk::uuid) and (keys_value is null or x.id=any(keys_value::uuid[])) and (p is null or x.provider_id=p) and (s is null or x.id=s) order by x.id desc limit least(greatest(lim,1),101);return;end if;
 if c='destinations' then return query select x.id::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','DESTINATION','label',x.label,'reference',x.label,'destination_id',x.id,'destination_label',x.label,'state',case when x.paused then 'PAUSED' else 'SIMULATED' end,'paused',x.paused,'revision',x.revision::text) from private.signal_destinations x  where x.tenant_id=t and (ak is null or x.id<ak::uuid) and (hk is null or x.id<=hk::uuid) and (keys_value is null or x.id=any(keys_value::uuid[])) and (d is null or x.id=d) order by x.id desc limit least(greatest(lim,1),101);return;end if;
 if c='routes' then return query select x.id::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','ROUTE','label',a.label||' → '||b.label,'reference','ROUTE','provider_id',v.id,'provider_label',v.label,'source_id',a.id,'source_label',a.label,'destination_id',b.id,'destination_label',b.label,'state',case when x.paused or a.paused or b.paused or v.paused then 'PAUSED' when v.authorization_status<>'SYNTHETIC_APPROVED' then 'CONFIGURED_DISABLED' else 'SIMULATED' end,'paused',x.paused,'authorization',v.authorization_status,'revision',x.revision::text) from private.signal_routes x join private.signal_sources a on a.tenant_id=x.tenant_id and a.id=x.source_id join private.signal_providers v on v.tenant_id=a.tenant_id and v.id=a.provider_id join private.signal_destinations b on b.tenant_id=x.tenant_id and b.id=x.destination_id where x.tenant_id=t and (ak is null or x.id<ak::uuid) and (hk is null or x.id<=hk::uuid) and (keys_value is null or x.id=any(keys_value::uuid[])) and (p is null or a.provider_id=p) and (s is null or a.id=s) and (d is null or b.id=d) order by x.id desc limit least(greatest(lim,1),101);return;end if;
 if c='events' then return query select x.sequence::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','EVENT','label','SIG-'||x.sequence,'reference','SIG-'||x.sequence,'event_id',x.id,'provider_id',v.id,'provider_label',v.label,'source_id',a.id,'source_label',a.label,'state',case when x.kind='RESTRICTED' then 'SOURCE_RESTRICTED' when x.kind='UNAVAILABLE' then 'SOURCE_UNAVAILABLE' else x.kind end,'revision',x.revision::text,'observed_at',x.original->>'observed_at','published_at',x.original->>'published_at','recorded_at',x.recorded_at,'parse_state',x.parse_state,'current',h.event_id=x.id,'signal',case when x.original->'interpretation'='null'::jsonb then null else jsonb_build_object('action',x.original#>'{interpretation,action}','direction',x.original#>'{interpretation,direction}','symbol',x.original#>'{interpretation,symbol}','order_type',x.original#>'{interpretation,order_type}','entry',x.original#>'{interpretation,entry}','stop_loss',x.original#>'{interpretation,stop_loss}','take_profits',x.original#>'{interpretation,take_profits}') end) from private.signal_events x join private.signal_sources a on a.tenant_id=x.tenant_id and a.id=x.source_id join private.signal_providers v on v.tenant_id=a.tenant_id and v.id=a.provider_id join private.signal_heads h on h.tenant_id=x.tenant_id and h.source_id=x.source_id and h.message_key=x.message_key where x.tenant_id=t and (ak is null or x.sequence<ak::bigint) and (hk is null or x.sequence<=hk::bigint) and (keys_value is null or x.sequence=any(keys_value::bigint[])) and (p is null or a.provider_id=p) and (s is null or a.id=s) order by x.sequence desc limit least(greatest(lim,1),101);return;end if;
 if c='deliveries' then return query select x.sequence::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','DELIVERY','label','OUT-'||x.sequence,'reference','OUT-'||x.sequence,'delivery_id',x.id,'event_id',e.id,'provider_id',v.id,'provider_label',v.label,'source_id',a.id,'source_label',a.label,'destination_id',b.id,'destination_label',b.label,'state',x.status,'code',private.signal_admin_code_v1(x.last_code),'revision',e.revision::text,'observed_at',e.original->>'observed_at','recorded_at',x.enqueued_at,'available_at',x.available_at,'acknowledged_at',ack.evidence->>'acknowledged_at','current',h.event_id=e.id,'claims',x.claims,'reclaims',x.reclaims,'failures',x.failures) from private.signal_deliveries x join private.signal_events e on e.tenant_id=x.tenant_id and e.id=x.event_id join private.signal_sources a on a.tenant_id=e.tenant_id and a.id=e.source_id join private.signal_providers v on v.tenant_id=a.tenant_id and v.id=a.provider_id join private.signal_destinations b on b.tenant_id=x.tenant_id and b.id=x.destination_id join private.signal_heads h on h.tenant_id=e.tenant_id and h.source_id=e.source_id and h.message_key=e.message_key left join lateral(select q.evidence from private.signal_delivery_history q where q.tenant_id=t and q.delivery_id=x.id and q.code in ('FAKE_ACK','RECONCILED_FAKE_ACK') order by q.sequence desc limit 1)ack on true where x.tenant_id=t and (ak is null or x.sequence<ak::bigint) and (hk is null or x.sequence<=hk::bigint) and (keys_value is null or x.sequence=any(keys_value::bigint[])) and (p is null or a.provider_id=p) and (s is null or a.id=s) and (d is null or b.id=d) and (j is null or x.id=j) and (st is null or x.status=st) order by x.sequence desc limit least(greatest(lim,1),101);return;end if;
 if c='history' then return query select x.sequence::text,private.signal_admin_base_v1()||jsonb_build_object('id',x.id,'kind','HISTORY','label','OUT-'||z.sequence||' · LOG-'||x.sequence,'reference','LOG-'||x.sequence,'delivery_id',x.delivery_id,'event_id',e.id,'provider_id',v.id,'provider_label',v.label,'source_id',a.id,'source_label',a.label,'destination_id',b.id,'destination_label',b.label,'revision',e.revision::text,'state','SIMULATED','code',private.signal_admin_code_v1(x.code),'recorded_at',x.recorded_at,'claims',x.claim,'acknowledged_at',case when x.code in ('FAKE_ACK','RECONCILED_FAKE_ACK') then x.evidence->>'acknowledged_at' else null end) from private.signal_delivery_history x join private.signal_deliveries z on z.tenant_id=x.tenant_id and z.id=x.delivery_id join private.signal_events e on e.tenant_id=z.tenant_id and e.id=z.event_id join private.signal_sources a on a.tenant_id=e.tenant_id and a.id=e.source_id join private.signal_providers v on v.tenant_id=a.tenant_id and v.id=a.provider_id join private.signal_destinations b on b.tenant_id=z.tenant_id and b.id=z.destination_id where x.tenant_id=t and (ak is null or x.sequence<ak::bigint) and (hk is null or x.sequence<=hk::bigint) and (keys_value is null or x.sequence=any(keys_value::bigint[])) and x.delivery_id=j order by x.sequence desc limit least(greatest(lim,1),101);return;end if;
 raise exception 'signal read invalid' using errcode='22023';
end;$$;

create function public.admin_signal_page_v1(target_tenant_id uuid,collection_value text default 'deliveries',provider_value uuid default null,source_value uuid default null,destination_value uuid default null,delivery_value uuid default null,status_value text default null,page_size_value integer default 25,cursor_value jsonb default null)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog set plan_cache_mode=force_custom_plan as $$
declare role_value text;scope_value text;started timestamptz:=statement_timestamp();ak text;hk text;rows_value jsonb;items_value jsonb;more boolean;next_value jsonb;n integer;count_keys integer;key_type text;
begin
 if auth.uid() is null or not private.has_tenant_role(target_tenant_id,array['super_admin','manager','support','analyst']::public.app_role[]) then raise exception 'signal read denied' using errcode='42501';end if;
 select m.role::text into role_value from public.tenant_members m where m.tenant_id=target_tenant_id and m.user_id=auth.uid() and m.status='active';
 if collection_value not in ('providers','sources','destinations','routes','events','deliveries','history') or collection_value is null or page_size_value is null or page_size_value not between 1 and 100
  or (status_value is not null and (collection_value<>'deliveries' or status_value not in ('PENDING','RUNNING','RETRY','FAKE_CONFIRMED','UNKNOWN','REVIEW','STALE','NO_EFFECT','STALE_ACK')))
  or (collection_value='history' and (delivery_value is null or provider_value is not null or source_value is not null or destination_value is not null))
  or (provider_value is not null and not exists(select 1 from private.signal_providers where tenant_id=target_tenant_id and id=provider_value))
  or (source_value is not null and not exists(select 1 from private.signal_sources where tenant_id=target_tenant_id and id=source_value and (provider_value is null or provider_id=provider_value)))
  or (destination_value is not null and not exists(select 1 from private.signal_destinations where tenant_id=target_tenant_id and id=destination_value))
  or (delivery_value is not null and (collection_value not in ('deliveries','history') or not exists(select 1 from private.signal_deliveries where tenant_id=target_tenant_id and id=delivery_value)))
  or (collection_value='providers' and (source_value is not null or destination_value is not null)) or (collection_value in ('sources','events') and destination_value is not null) or (collection_value='destinations' and (provider_value is not null or source_value is not null)) then
   raise exception 'signal read invalid; refresh' using errcode='22023';end if;
 scope_value:=private.fse_hash(private.fse_canonical(jsonb_build_array('SIGNAL_ADMIN1',target_tenant_id,auth.uid(),role_value,collection_value,provider_value,source_value,destination_value,delivery_value,status_value,page_size_value)));
 key_type:=case when collection_value in ('providers','sources','destinations','routes') then 'uuid' else 'bigint' end;
 if cursor_value is not null then begin
  if not private.fse_keys(cursor_value,array['version','scope','started_at','after','anchor']) or cursor_value->'version' is distinct from '1'::jsonb or cursor_value->>'scope' is distinct from scope_value or octet_length(cursor_value::text)>1024 then raise exception 'invalid';end if;
  started:=(cursor_value->>'started_at')::timestamptz;ak:=cursor_value->>'after';hk:=cursor_value->>'anchor';
  if started is null or not isfinite(started) or started>statement_timestamp()+interval '1 second' or started<statement_timestamp()-interval '30 minutes' or ak is null or hk is null then raise exception 'invalid';end if;
  if key_type='uuid' then if ak::uuid>hk::uuid or ak<>ak::uuid::text or hk<>hk::uuid::text then raise exception 'invalid';end if;
  else if ak !~ '^[1-9][0-9]{0,18}$' or hk !~ '^[1-9][0-9]{0,18}$' or ak::bigint>hk::bigint then raise exception 'invalid';end if;end if;
  select count(*) into count_keys from private.signal_admin_rows_v1(target_tenant_id,collection_value,provider_value,source_value,destination_value,delivery_value,status_value,null,null,array[ak,hk],3);
  if count_keys<>(case when ak=hk then 1 else 2 end) then raise exception 'invalid';end if;
 exception when others then raise exception 'signal read invalid; refresh' using errcode='22023';end;end if;
 select coalesce(jsonb_agg(jsonb_build_object('key',q.key_value,'value',q.row_value) order by q.ord),'[]'::jsonb) into rows_value
 from private.signal_admin_rows_v1(target_tenant_id,collection_value,provider_value,source_value,destination_value,delivery_value,status_value,ak,hk,null,page_size_value+1) with ordinality q(key_value,row_value,ord);
 n:=jsonb_array_length(rows_value);more:=n>page_size_value;
 select coalesce(jsonb_agg(value->'value' order by ord),'[]'::jsonb) into items_value from jsonb_array_elements(rows_value) with ordinality z(value,ord) where ord<=page_size_value;
 hk:=coalesce(hk,rows_value->0->>'key');
 if more then next_value:=jsonb_build_object('version',1,'scope',scope_value,'started_at',started,'after',rows_value->(page_size_value-1)->>'key','anchor',hk);end if;
 return jsonb_build_object('version',1,'mode','SYNTHETIC','financial_authority','NONE','live_authority','NONE','collection',collection_value,'page_size',page_size_value,'items',items_value,'has_more',more,'next_cursor',next_value,'consistency','LIVE_KEYSET_REFRESH_FOR_CHANGES');
end;$$;
create function public.admin_signal_summary_v1(target_tenant_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog set plan_cache_mode=force_custom_plan as $$
declare counts_value jsonb;latency_value jsonb;enabled_value boolean;begin
 if auth.uid() is null or not private.has_tenant_role(target_tenant_id,array['super_admin','manager','support','analyst']::public.app_role[]) then raise exception 'signal read denied' using errcode='42501';end if;
 select enabled into enabled_value from private.signal_controls where tenant_id=target_tenant_id;
 select jsonb_agg(jsonb_build_object('status',q.status,'value',least(q.n,10000),'complete',q.n<=10000) order by q.status) into counts_value from
 (select x.status,(select count(*) from(select 1 from private.signal_deliveries j where j.tenant_id=target_tenant_id and j.status=x.status order by j.sequence desc limit 10001)b)n
 from unnest(array['PENDING','RUNNING','RETRY','UNKNOWN','REVIEW','STALE','FAKE_CONFIRMED','NO_EFFECT','STALE_ACK']) x(status))q;
 with sample as (select j.id,j.completed_at,e.original->>'observed_at' observed from private.signal_deliveries j join private.signal_events e on e.id=j.event_id and e.tenant_id=j.tenant_id
  where j.tenant_id=target_tenant_id and j.completed_at is not null order by j.completed_at desc,j.sequence desc limit 1000),
 measured as(select extract(epoch from((h.evidence->>'acknowledged_at')::timestamptz-s.observed::timestamptz))*1000 ms,(h.evidence->>'acknowledged_at')::timestamptz ack from sample s
  join lateral(select q.evidence from private.signal_delivery_history q where q.tenant_id=target_tenant_id and q.delivery_id=s.id and q.code in ('FAKE_ACK','RECONCILED_FAKE_ACK') order by q.sequence desc limit 1)h on true),
 valid as(select ms,ack from measured where ms>=0 and ms<'Infinity'::numeric)
 select jsonb_build_object('sampled',(select count(*) from sample),'valid',count(*),'p50_ms',percentile_disc(.5) within group(order by ms),'p95_ms',percentile_disc(.95) within group(order by ms),'p99_ms',percentile_disc(.99) within group(order by ms),'max_ms',max(ms),'last_ack_at',max(ack)) into latency_value from valid;
 return jsonb_build_object('version',1,'mode','SYNTHETIC','financial_authority','NONE','live_authority','NONE','enabled',coalesce(enabled_value,false),'observed_at',statement_timestamp(),'counts',counts_value,'latency',latency_value,'oldest_pending_at',(select min(b.enqueued_at) from unnest(array['PENDING','RETRY','RUNNING','UNKNOWN'])z(status) join lateral(select a.enqueued_at from private.signal_deliveries a where a.tenant_id=target_tenant_id and a.status=z.status order by a.sequence limit 1)b on true));
end;$$;
revoke all on function private.signal_admin_base_v1(),private.signal_admin_code_v1(text),private.signal_admin_rows_v1(uuid,text,uuid,uuid,uuid,uuid,text,text,text,text[],integer) from public,anon,authenticated,service_role;
revoke all on function public.admin_signal_page_v1(uuid,text,uuid,uuid,uuid,uuid,text,integer,jsonb),public.admin_signal_summary_v1(uuid) from public,anon,authenticated,service_role;
grant execute on function public.admin_signal_page_v1(uuid,text,uuid,uuid,uuid,uuid,text,integer,jsonb),public.admin_signal_summary_v1(uuid) to authenticated;
